/* Microfix 3.8.36: clean project action icons inside Layers */
(()=>{
  const pop=document.getElementById("projectPopover");if(!pop)return;
  const icons={renameProject:"i-text",newProject:"i-plus",openProjectFile:"i-folder",saveProjectFile:"i-export"};
  Object.entries(icons).forEach(([id,icon])=>{
    const btn=document.getElementById(id);if(!btn||btn.querySelector(".project-action-icon"))return;
    const mark=document.createElement("span");mark.className="project-action-icon";mark.innerHTML=`<svg aria-hidden="true"><use href="#${icon}"/></svg>`;btn.prepend(mark);
  });
})();

/* Microfix 3.8.36: project actions are a flat list, not a card */
.layers-panel #projectPopover.layers-project-accordion{border:0!important;border-radius:0!important;background:transparent!important;box-shadow:none!important;backdrop-filter:none!important;margin:0 12px!important;padding:2px 0 8px!important}
.layers-panel #projectPopover.layers-project-accordion>button{display:flex!important;align-items:center!important;gap:9px!important;width:100%;min-height:34px;padding:0 6px!important;border:0!important;border-radius:7px!important;background:transparent!important;text-align:left;color:var(--text);font-size:11px}
.layers-panel #projectPopover.layers-project-accordion>button:hover{background:color-mix(in srgb,var(--surface-2) 72%,transparent)!important}
.project-action-icon{width:18px;height:18px;min-width:18px;display:grid;place-items:center;color:var(--muted)}
.project-action-icon svg{width:14px;height:14px;display:block}
.layers-panel #projectPopover.layers-project-accordion>button:hover .project-action-icon{color:var(--text)}
.layers-project-divider{height:1px!important;margin:7px 0 3px!important;background:var(--line)!important}
.layers-preview-setting{padding-left:6px!important;padding-right:6px!important}
